// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1 ether * 1000000);
        ReentrantAttacker a = new ReentrantAttacker(c);
        vm.deal(address(a), amount);

        bool ok = true;
        try a.attack(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // A re-entrant withdrawAll must never succeed: the inner re-entrant
        // call fails on the lock, and the reference reverts on its failure.
        assertTrue(!ok, "withdrawAll completed despite failing re-entrant call");
    }
}

contract ReentrantAttacker {
    ReentrancyDAO public c;
    bool private entered;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    function attack(uint256 amount) external {
        c.deposit{value: amount}();
        c.withdrawAll();
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.withdrawAll();
        }
    }
}
